var e={rfidSeq:{legend:{msg:`SPI-Zugriff oder Funkframe (orange: dieser Schritt)`,wait:`Reader-Task wartet (IRQ-Draht oder Polling)`},lanes:{names:[`Reader-Task`,`MFRC522`,`Karte`],subs:[`ESP32-Kern 0`,`der Reader-Chip`,`keine Batterie`]},flows:{wake:{label:`Aufwecken (WUPA → ATQA)`,steps:[{title:`Den Frame in den Chip laden`,text:`Per SPI schreibt der Reader-Task WUPA (52h) in den 64-Byte-FIFO des Chips und sagt ihm, nur 7 Bits zu senden: ein kurzer Frame.`},{title:`Senden, dann lauschen`,text:`Ein Befehl lässt den Chip das FIFO senden und dann auf Empfang umschalten. Ab hier wartet der Reader-Task: am IRQ-Draht oder indem er ComIrqReg immer wieder liest.`},{title:`100 % ASK: das Feld pausiert`,text:`Der Chip moduliert sein eigenes 13,56-MHz-Feld: eine Pause von etwa 3 µs am Anfang (Z) oder in der Mitte (X) eines Bits, oder keine (Y). Die Karte wird durch dieses Feld versorgt, auch durch die Pausen hindurch.`},{msg:`aufwecken · 86 µs warten`,title:`Die Karte wacht auf und wartet, bis sie dran ist`,text:`Der Chip der Karte startet aus dem Feld, dekodiert WUPA und wartet dann eine feste Zeit, bevor er antwortet. Jede Karte wartet exakt gleich lang, also antworten alle im selben Moment: Das macht Kollisionen möglich.`},{title:`Lastmodulation: die Karte antwortet`,text:`Die Karte kann nicht senden. Sie schaltet eine Last an ihrer Spule mit 847 kHz (fc/16) an und aus, und die Antenne des Readers spürt, wie ihr eigenes Feld wackelt. Manchester-kodiert, 2 Bytes.`},{title:`Der Chip sagt „fertig“`,text:`Der Chip setzt RxIRq und IdleIRq in ComIrqReg. Mit IRQ-Draht fällt der Pin auf Low und weckt den Reader-Task sofort; ohne ihn hat der Task ComIrqReg per SPI abgefragt (R6 zählt die Kosten).`},{msg:`FIFO lesen`,title:`Die Antwort einsammeln`,text:`Keine Fehler, 2 Bytes warten, letztes Byte komplett. Der Treiber reicht ATQA an die Protokollschicht weiter.`}]},select:{label:`Select (UID → SAK)`,steps:[{title:`Wer bist du?`,text:`SEL 93h = Cascade Level 1. NVB 20h = 2 Bytes gesendet, keine zusätzlichen Bits: „sag mir alle 32 Bits deiner UID“.`},{title:`UID + BCC`,text:`Die Karte sendet ihre 4 UID-Bytes und ein Prüfbyte, das XOR aller vier. Bei zwei Karten kollidieren hier ihre Bits (R3).`},{msg:`BCC · CRC_A prüfen`,title:`Prüfen, dann ein CRC anhängen`,text:`Der Treiber prüft das BCC und hängt dann ein 2-Byte-CRC_A an den SELECT-Frame (R6 lässt die CRC-Einheit des Chips gegen den ESP32 antreten, der dieselbe Rechnung macht).`},{title:`Genau diese SELECTen`,text:`NVB 70h: 7 ganze Bytes folgen. Nur die Karte mit genau dieser UID antwortet; jede andere wird still.`},{title:`SAK: was für eine Karte`,text:`08h: MIFARE Classic 1K, und Bit 2 ist nicht gesetzt, also ist die UID komplett. Wäre Bit 2 gesetzt, ginge die UID auf Cascade Level 2 (95h) weiter.`},{title:`HLTA: schlafen gehen`,text:`Unser Poll legt die Karte sofort schlafen. Eine angehaltene Karte ignoriert REQA, wacht aber bei WUPA auf, also findet der nächste Poll (80 ms später) sie wieder: So weiß die Kartenansicht, dass sie noch da ist.`}]},read:{label:`Authentifizieren + Block 4 lesen`,steps:[{title:`Dem Chip den Schlüssel geben`,text:`12 Bytes ins FIFO: AUTH mit Schlüssel A (60h), Block 4, der 6-Byte-Schlüssel, die letzten 4 UID-Bytes. Dann der Befehl MFAuthent: Den Rest macht der Chip allein.`},{title:`Durchgang 1: welcher Sektor, welcher Schlüssel`,text:`Der Chip bittet die Karte, den Sektor von Block 4 (Sektor 1) mit Schlüssel A zu öffnen.`},{msg:`Challenge nT`,title:`Durchgang 2: die Challenge der Karte`,text:`Die Karte antwortet mit einer 4-Byte-Zufallszahl.`},{msg:`nR + Antwort`,title:`Durchgang 3: der Reader beweist, dass er den Schlüssel hat`,text:`Der Chip sendet seine eigene Zufallszahl und eine Antwort auf die Challenge der Karte, beide mit dem Schlüssel berechnet. Ab hier verschlüsselt Crypto1 jeden Frame.`},{msg:`Antwort der Karte`,title:`Auch die Karte beweist es`,text:`Die Antwort der Karte zeigt, dass sie denselben Schlüssel kennt. Der Chip setzt MFCrypto1On in Status2Reg; der Treiber prüft es.`},{msg:`30 04 + CRC (verschlüsselt)`,title:`Block 4 LESEN`,text:`Das FIFO enthält Klartext-Bytes; der Chip verschlüsselt sie auf dem Weg nach draußen. Der Sniffer markiert diese Frames als „in der Luft verschlüsselt“.`},{msg:`16 Bytes + CRC`,title:`Der Block`,text:`18 Bytes kommen zurück, vom Chip entschlüsselt.`},{msg:`18 Bytes → ESP32`,title:`Das CRC selbst prüfen`,text:`Der Treiber liest 18 Bytes aus dem FIFO und prüft CRC_A über die ersten 16. Ein falsches CRC heißt, der Frame wurde gestört: Der Stresstest in R6 zählt, wie oft.`}]},credits:{label:`Guthaben nutzen 3`,steps:[{title:`Den Wert laden`,text:`Die Karte prüft, ob Block 8 ein gültiger Wertblock ist (Wert, invertierter Wert, Wert, Adresse ×4) und lädt ihn in ihr internes Register. NAK, wenn das Format kaputt ist.`},{title:`Im Backup speichern`,text:`TRANSFER schreibt das Register in Block 9. Das Backup enthält jetzt den Wert von vor der Änderung.`},{title:`Abziehen, auf der Karte`,text:`Die Karte lädt Block 8 und zieht den Operanden in ihrem Register ab. Block 8 selbst ändert sich noch nicht.`},{title:`Übernehmen`,text:`Bis zu diesem TRANSFER steht in Block 8 noch 50. Die Karte schreibt den ganzen 16-Byte-Block oder nichts, also hinterlässt eine mittendrin weggezogene Karte 50 oder 47, nie eine kaputte Zahl.`},{msg:`8 und 9 lesen`,title:`Prüfen, was die Karte jetzt sagt`,text:`Die Firmware liest beide Blöcke zurück und dekodiert sie.`}]}}},doorSeq:{legend:{msg:`HTTP, WebSocket oder Funk (orange: dieser Schritt)`,wait:`die App wartet auf das Board`},lanes:{names:[`React-App`,`Vite-Server`,`Webserver`,`Reader-Task`,`Karte`],subs:[`dein Browser`,`auf deinem Mac`,`Board, Kern 1`,`Board, Kern 0`,`dein Tag`]},flows:{tap:{label:`Ein Tap`,steps:[{title:`Die Karte sagt, wer sie ist`,text:`Aufwecken, Antikollision und Select wie in R2: Alles, was die Karte beisteuert, ist ihre UID.`},{msg:`aus der Liste entscheiden`,title:`Das Board entscheidet anhand seiner eigenen Liste`,text:`registry.tap() schlägt die UID nach und prüft die Regeln der Reihe nach (gesperrt, Lockdown, Uhrzeit, Enddatum, Zeiten, Nutzungen). Nichts auf der Karte wird gelesen oder ihm vertraut.`},{title:`Die Tür öffnet sich`,text:`Das Vorhängeschloss auf dem Bildschirm schwingt auf, die LED wird grün und ein 5-Sekunden-Countdown startet. Abgelehnte Taps zeigen 2 s lang DENIED mit dem Grund, LED rot.`},{msg:`Event-JSON`,title:`Ein Event fürs Log`,text:`Der Reader-Task legt eine JSON-Nachricht in seine Outbox; loop() auf dem anderen Kern sendet sie an jeden WebSocket-Client.`},{msg:`WebSocket-Push`,title:`Die App hört es sofort`,text:`Über den Proxy von Vite zum Browser: eine neue Zeile im Zugriffslog, das Türpanel wird grün. Jede Sekunde folgt eine Statusmeldung.`}]},block:{label:`Block aus der App`,steps:[{title:`Du drückst Sperren`,text:`Die App sendet nur, was sich geändert hat. Sie hat kein Token: Der Browser hält es nie.`},{title:`Der Dev-Server fügt das Token hinzu`,text:`Der Proxy von Vite auf deinem Mac fügt den Header aus door-app/.env hinzu und leitet die Anfrage über dein WLAN weiter.`},{msg:`prüfen, aktualisieren, speichern`,title:`Das Board prüft zuerst alles`,text:`Das Token wird in konstanter Zeit verglichen, jedes Feld validiert, dann ändert registry.update() die Karte unter ihrem Mutex und speichert die Liste im NVS.`},{msg:`200 + die Karte`,title:`Die Antwort, mit dem, was ein Tap jetzt tun würde`,text:`Die Karte kommt mit ihrem neuen Zustand zurück, und eine WebSocket-Nachricht „cards“ aktualisiert jede offene App.`},{msg:`nächster Tap`,title:`Der nächste Tap`,text:`Dieselbe Karte, dieselbe UID: Auf der Karte hat sich nichts geändert.`},{msg:`gesperrt → DENIED`,title:`Gesperrt gewinnt zuerst`,text:`Die allererste Regel nach „in der Liste?“ ist „gesperrt?“, also spielt es keine Rolle, was die Karte sonst darf: DENIED · blocked, LED rot.`}]},copy:{label:`Eine Karte kopieren`,steps:[{title:`Diese Karte auf eine andere kopieren`,text:`Die weiße Karte liegt auf dem Leser. Über den Proxy, mit dem Token; der Webserver reiht einen Job ein und antwortet sofort.`},{title:`Die Quelle lesen, Sektor für Sektor`,text:`Werksschlüssel A für Sektor 1, dann Blöcke 4, 5 und 6 LESEN (je 16 Bytes, mit CRC_A), dasselbe für Sektor 2. Die Trailer werden nicht kopiert: Schlüssel und Zugriffsbits bleiben, wo sie sind.`},{msg:`auf eine andere Karte warten`,title:`Das Board wartet auf die zweite Karte`,text:`Der Bildschirm zeigt COPY: 2ND CARD und die LED blinkt violett. Die Quelle, die noch da liegt, zählt nicht; sie anzuheben und wieder aufzulegen auch nicht.`},{title:`Du legst den Schlüsselanhänger hin`,text:`Eine andere UID: Das ist das Ziel.`},{msg:`WRITE 4 … 10, zurücklesen`,title:`Jeden Block schreiben, zurücklesen`,text:`WRITE hat zwei Schritte (Befehl → ACK, 16 Bytes → ACK); dann prüft READ, ob die Karte es wirklich hält. Nur Blöcke, die die Zugriffsbits des Ziels für Schlüssel A erlauben; ein Sektor, der sich nicht öffnet, wird übersprungen.`},{msg:`Job 9 ok`,title:`6 von 6 Blöcken kopiert`,text:`Das Ergebnis erreicht die App als Toast und das Log bekommt eine Zeile „Daten hierher kopiert“. Tipp jetzt den Schlüsselanhänger an: Er öffnet sich als Schlüsselanhänger, denn die Tür schlägt seine UID nach, die sich nicht geändert hat.`}]},enroll:{label:`Eine Karte hinzufügen`,steps:[{title:`Name und Rolle`,text:`Über den Proxy, mit dem Token. Der Webserver reiht nur einen Job für den Reader-Task ein (ein Besitzer pro Chip) und antwortet sofort.`},{msg:`Job 7 im Briefkasten`,title:`Ein Job, kein Warten`,text:`Die HTTP-Anfrage ist schon beantwortet; das Ergebnis kommt später über den WebSocket. Netzwerk-Handler dürfen nie blockieren.`},{msg:`20 s warten, blaue LED`,title:`Das Board wartet auf eine Karte, die es nicht kennt`,text:`Der Bildschirm zeigt ADD A CARD und die LED blinkt blau. Eine Karte, die schon in der Liste ist, wird mit ihrem Namen abgelehnt.`},{title:`Du legst den Schlüsselanhänger hin`,text:`Nicht in der Liste: Er wird die neue Karte. Gäste starten mit 5 Nutzungen.`},{msg:`Job 7 ok + cards`,title:`Das Ergebnis erreicht die App`,text:`Eine Nachricht „job“ mit id 7 löst das wartende Promise der App auf (ein Toast), und eine Nachricht „cards“ aktualisiert die Liste.`}]}}},friendsSeq:{lanes:{names:[`friends-app`,`Vite-Server`,`Webserver`,`Reader-Task`,`Karte`],subs:[`Browser / Tablet`,`auf deinem Mac`,`Board, Kern 1`,`Board, Kern 0`,`dein Tag`]},flows:{tap:{label:`Karte 1 antippen`,steps:[{title:`Die Karte sagt, wer sie ist`,text:`Aufwecken, Antikollision und Select wie in R2. R8 liest sonst nichts von der Karte: keine Blöcke, keine Schlüssel.`},{msg:`wer wohnt hier?`,title:`Das Board schlägt die UID nach`,text:`friends::List::tap() findet Karte 1, zählt den Besuch und speichert die Liste im NVS. Der Freund ist nur ein Id-String.`},{msg:`Foxy springt heraus`,title:`Der eigene Bildschirm des Boards`,text:`Die Bühnenansicht lässt Foxy mit Überschwung aus der Karte wachsen, Sterne fliegen in seinen Farben heraus, dann hüpft er: „Hi again! Foxy · card 1 · 5 visits“. Die LED blitzt orange.`},{msg:`Tap-JSON`,title:`Eine Nachricht für jede App`,text:`Der Reader-Task legt sie in seine Outbox; loop() auf dem anderen Kern sendet sie über den WebSocket.`},{msg:`WebSocket-Push`,title:`Die 3D-Bühne spielt`,text:`Die App stellt Foxy auf die Bühne: ein Puff, ein Sprung aus Karte 1, eine Doppeldrehung, goldene Sterne, der Himmel wird zum Sonnenuntergang und seine Melodie spielt. Tipp jetzt Karte 2 an, und Bolt gesellt sich tanzend dazu.`}]},newcard:{label:`Eine neue Karte bekommt einen Freund`,steps:[{title:`Eine Karte, die das Board nie gesehen hat`,text:`Dasselbe Select wie immer, aber diese UID ist nicht in der Liste.`},{msg:`als Karte 2 hinzufügen, noch niemand`,title:`Sie fügt sich selbst hinzu`,text:`Bis zu 12 Karten. character = "": Der Bildschirm zeigt eine wackelnde „?“-Karte: „New card! Give it a friend“.`},{title:`Die App fragt nach einem Freund`,text:`Die Sprechblase sagt „New card 2! Who lives here?“ und die Kachel von Karte 2 ruft nach Aufmerksamkeit.`},{title:`Du ziehst Bolt auf Karte 2`,text:`Oder tipp Bolt an, dann die Karte. Der Browser hat kein Token.`},{title:`Der Dev-Server fügt das Token hinzu`,text:`Der Proxy von Vite fügt es aus friends-app/.env hinzu (dasselbe Token wie bei W2 und R7).`},{msg:`Id prüfen, speichern`,title:`Das Board prüft die Id`,text:`Nur Ids aus characters.h werden akzeptiert (GET /api/cast listet sie). Die Kartenliste ändert sich unter ihrem Mutex und geht ins NVS.`},{title:`Sofort zeigen`,text:`Die App bittet das Board, Karte 2 zu zeigen (zählt nicht als Besuch): Bolt springt gleichzeitig auf dem Bildschirm und in 3D heraus.`}]}}},controls:{back:`◀ Zurück`,next:`Weiter ▶`,play:`▶ Abspielen`,pause:`❚❚ Pause`,playback:`Wiedergabe`,turn:`Drehen`,stepOf:`Schritt {{step}} / {{count}}`},spi:{register:`Register`,readOrWrite:`Lesen oder schreiben`,read:`lesen`,write:`schreiben 03h`,fault:`Zu simulierender Fehler`,faults:{none:`richtig verkabelt`,miso:`MISO-Draht lose`,power:`kein 3,3 V`,ss:`SDA-Draht (Chip Select) lose`},prevBit:`Vorheriges Bit`,nextBit:`Nächstes Bit`,pause:`Pause`,play:`Abspielen`,playShort:`▶ Abspielen`,diagram:`Logikanalysator-Ansicht einer SPI-Übertragung: Chip Select, Takt, MOSI und MISO über 16 Taktzyklen.`,dontCare:`egal`,dontCareWrite:`egal (Schreiben)`,byte0:`Byte 0 · MOSI {{hex}}h`,byte1Miso:`Byte 1 · MISO {{hex}}h`,byte1Mosi:`Byte 1 · MOSI {{hex}}h`,regs:{VersionReg:`92h = MFRC522 Version 2.0`,ComIrqReg:`14h nach dem Reset: IdleIRq + LoAlertIRq`,TxControlReg:`83h: beide Antennentreiber an (Bits 1-0)`,RFCfgReg:`40h: Empfängerverstärkung 100b = 33 dB (48h direkt nach einem Reset)`},bits:{rwRead:{key:`Bit 7 des Adressbytes:`,text:`1 = lesen. MSB zuerst; Daten ändern sich an der fallenden Taktflanke und werden an der steigenden gelesen (SPI-Modus 0).`},rwWrite:{key:`Bit 7 des Adressbytes:`,text:`0 = schreiben. MSB zuerst; Daten ändern sich an der fallenden Taktflanke und werden an der steigenden gelesen (SPI-Modus 0).`},addrRead:{key:`Bits 6-1:`,text:`die Registeradresse {{a}}h = {{bits}}, ein Bit pro Takt. Also liest sich {{name}} als {{addr}}h.`},addrWrite:{key:`Bits 6-1:`,text:`die Registeradresse {{a}}h = {{bits}}, ein Bit pro Takt. Also schreibt sich {{name}} als {{addr}}h.`},zero:{key:`Bit 0:`,text:`immer 0. Der Chip hat 64 Register, 6 Bits reichen.`},write:{key:`Byte 1:`,text:`der zu schreibende Wert, {{data}}h. MISO trägt beim Schreiben nichts Brauchbares.`},answer:{key:`Byte 1 auf MISO:`,text:`{{answer}}h. {{what}}. Währenddessen sendet MOSI 00 (oder im Burst die nächste Adresse).`},power:{key:`Byte 1 auf MISO:`,text:`00h. Ein Chip ohne Strom kann MISO nicht auf High treiben: Jedes Register liest 00. Die Firmware gibt „nothing (MISO stuck low?)“ aus: prüf 3,3V und GND.`},float:{key:`Byte 1 auf MISO:`,text:`FFh (meistens). Niemand treibt MISO, also schwebt es auf High: Jedes Register liest FF. Der Chip antwortet, aber die Antwort kommt nie an.`},floatSs:{key:`Byte 1 auf MISO:`,text:`FFh (meistens). Niemand treibt MISO, also schwebt es auf High: Jedes Register liest FF. Bei losem SDA wird der Chip nie ausgewählt und bleibt stumm.`}}},anticoll:{steps:{identical:{title:`Identische UIDs`,text:`Zwei Karten teilen nie eine UID (das ist ihr Sinn). Ändere ein Byte.`},wake:{title:`WUPA: beide Karten wachen auf`,text:`Beide antworten im selben Moment mit ATQA 04 00. Identische Bits übereinander sehen aus wie eine Karte, also noch keine Kollision.`},all:{title:`93 20: „alle mal, sendet eure UID“`,text:`Beide Karten senden 32 Bits gleichzeitig. Die Bits 1–{{shared}} sind gleich und kommen sauber an. Bei Bit {{p}} sendet eine Karte 0 und die andere 1: Der Reader hört beide Hälften des Bits, eine Kollision. CollReg sagt CollPos = {{p}}. Bits danach lesen sich als 0 (ValuesAfterColl = 0).`},pick:{title:`Bei Bit {{p}} die 1 wählen, nochmal fragen`,text:`Der Reader sendet die {{p}} Bits, die er jetzt kennt, mit einer 1 am Ende: SEL 93, NVB {{nvb}}h ({{bytes}} ganze Bytes + {{bits}} Bits). Bit {{p}} ist Bit {{bitIn}} von UID-Byte {{byte}}. Karte {{loser}} hat dort 0, also hört sie bis zum nächsten REQA oder WUPA auf zu antworten.`},rest:{title:`Nur Karte {{winner}} antwortet den Rest`,text:`Karte {{winner}} sendet die Bits {{after}}–32 und ihr BCC. Keine Kollision: Der Reader hat jetzt die volle UID {{winnerUid}}, und BCC {{bcc}} stimmt.`},select:{title:`SELECT {{winnerUid}} → SAK 08`,text:`93 70 + UID + BCC + CRC_A. Karte {{winner}} ist jetzt ACTIVE, bereit für Authentifizierung und Lesen. Der Walk nimmt bei einer Kollision immer die 1, darum gewinnt jedes Mal dieselbe Karte.`},halt:{title:`HLTA Karte {{winner}}, dann wieder REQA`,text:`Karte {{winner}} geht in HALT und ignoriert REQA. Karte {{loser}} hat nur gewartet (READY → zurück zu IDLE), also antwortet sie allein auf REQA.`},second:{title:`93 20 → Karte {{loser}} allein: {{loserUid}}`,text:`Diesmal keine Kollision. SELECT, SAK, HLTA. Das nächste REQA bekommt gar keine Antwort: Das Inventar hat 2 Karten gefunden. Das gibt der Inventarbefehl der Firmware aus.`}},tree:{label:`Der Binärbaum, dem der Walk folgt: gemeinsame Bits, dann eine Verzweigung bei der ersten Kollision.`,shared:`Bits 1–{{last}}: gemeinsam ({{count}} Bits)`,collision:`Bit {{p}}: Kollision`,zero:`Bit = 0`,one:`Bit = 1, zuerst genommen`,card:`Karte {{name}}`,foundFirst:`Karte {{name}} ✓ zuerst gefunden`,foundSecond:`Karte {{name}} ✓ als zweite gefunden`},uidA:`UID von Karte A`,uidB:`UID von Karte B`,uidAHint:`UID von Karte A, 4 Bytes in Hex`,uidBHint:`UID von Karte B, 4 Bytes in Hex`,random:`Zufallspaar`,grid:`Die UID-Bits beider Karten und was der Reader hört, in der Reihenfolge, in der sie wandern.`,rowCard:`Karte {{name}} {{uid}}`,rowHears:`Reader hört`,rowBit:`Bit-Nr.`},access:{data:{c0:`lesen und schreiben mit Schlüssel A oder B; erhöhen, verringern (Transport-Einstellung)`,c1:`lesen, verringern mit A oder B; kein Schreiben (ein Wert, der nur sinken kann)`,c2:`lesen mit A oder B; nie wieder beschrieben`,c3:`lesen und schreiben nur mit Schlüssel B`,c4:`lesen mit A oder B, schreiben mit B`,c5:`lesen nur mit Schlüssel B; nie beschrieben`,c6:`lesen mit A oder B; schreiben und erhöhen mit B; verringern mit A oder B (Wertblock)`,c7:`nichts, nie`},trailer:{c0:`Schlüssel A schreibt beide Schlüssel; Zugriffsbits fest; Schlüssel B lesbar (kann also kein Schlüssel sein)`,c1:`Schlüssel A schreibt Schlüssel und Zugriffsbits (Transport-Einstellung)`,c2:`nichts lässt sich mehr ändern; Schlüssel B lesbar`,c3:`Schlüssel B schreibt Schlüssel und Zugriffsbits`,c4:`Schlüssel B schreibt die Schlüssel; Zugriffsbits fest`,c5:`Schlüssel B schreibt die Zugriffsbits; Schlüssel fest`,c6:`nichts lässt sich mehr ändern`,c7:`nichts lässt sich mehr ändern`},presets:{factory:`Werkseinstellung FF 07 80`,values:`Wertblöcke`,readOnly:`schreibgeschützt, für immer`},typeBytes:`oder Typ-Bytes 6–8`,colBlock:`Block`,colAllows:`Was er erlaubt`,rowTrailer:`Trailer`,rowBlock:`Block {{n}}`,theTrailer:`der Trailer`,bitOf:`C{{n}} von {{block}}`,invertedBitOf:`invertiertes C{{n}} von {{block}}`,byte:`Byte {{n}}`,byteNote:`{{bits}} · jede Hälfte: Blöcke 3 2 1 0`,inconsistent:`<b>Inkonsistent:</b> Die invertierten Kopien passen nicht. Eine Karte lehnt so einen Trailer ab oder sperrt den Sektor.`,locked:`<b>Schreib das nie auf eine Karte.</b> Mit der Trailer-Einstellung {{bits}} kann kein Schlüssel die Schlüssel dieses Sektors je wieder ändern. Die Firmware des Labs schreibt Trailer gar nicht erst.`},value:{value:`Wert`,address:`Adressbyte`,add:`10 addieren`,use:`3 nutzen`,block:`Die 16 Bytes eines MIFARE-Wertblocks: {{bytes}}`,legend:{value:`Wert, little-endian (Bytes 0–3 und 8–11)`,inverted:`Wert invertiert (4–7)`,address:`Adresse`,addressInverted:`Adresse invertiert`},refused:`Nicht genug Guthaben: Die Firmware prüft das Guthaben, bevor sie die Karte bittet zu verringern.`,explain:`{{value}} = {{bytes}} (niedrigstes Byte zuerst). Dreimal gespeichert, einmal invertiert: Die Karte lehnt INCREMENT, DECREMENT und RESTORE bei einem Block ab, dessen Kopien nicht übereinstimmen. Das Adressbyte ist für dich frei (wir legen die Blocknummer hinein).`},field3d:{stage:`3D-Ansicht: die RC522-Platine mit ihrer Antennenspule, die Magnetfeldlinien darum und eine Karte darüber. Ziehen zum Drehen.`,fallback:`Das Diagramm und die Regler darunter funktionieren trotzdem.`,height:`Kartenhöhe über der Antenne`,gain:`Empfängerverstärkung (RFCfgReg)`,send:`▶ WUPA senden`,slice:`Eine Scheibe`,powered:`Karte versorgt`,unpowered:`Karte hat keinen Strom`,nothingToHear:`Reader hört es: nichts zu hören`,heard:`Reader hört es`,unheard:`Reader kann es nicht hören`,range:`Reichweite bei {{db}} dB: etwa {{mm}} mm`,air:`Was gerade in der Luft ist`,symbols:{start:`Start`,bit:`Bit {{bit}} = {{value}}`,end0:`Ende 0`,end:`Ende`},labels:{coil:`Antennenspule · 13,56 MHz`,chip:`MFRC522`,pins:`8 Pins → ESP32`,cardCoil:`Kartenspule: Strom + Antenne`,cardChip:`Kartenchip (keine Batterie)`},captions:{field:{title:`Das Feld`,text:`Die Antenne ist eine flache Spule auf der Platine. 13,56 Millionen Mal pro Sekunde kehrt sich ihr Strom um, und mit ihm das Magnetfeld darum: Die Linien verlassen die Mitte der Spule, biegen herum und kommen zurück. Hier kehrt es sich alle 2 Sekunden um.`},send:{title:`Der Reader sendet WUPA`,text:`100 % ASK: Für jedes Bit schaltet der Chip sein Feld für etwa 3 µs aus, am Anfang (Z) oder in der Mitte (X) des Bits, oder gar nicht (Y). 7 Bits plus Start und Ende dauern etwa 85 µs; hier je eine Drittelsekunde. Die Karte behält ihren Strom durch die Lücken.`},wake:{title:`Die Karte wacht auf und wartet`,text:`Ihr Chip ist aus dem Feld hochgefahren und hat WUPA dekodiert. Jede Karte wartet exakt gleich lang (etwa 86 µs), bevor sie antwortet, also antworten alle Karten im Feld gleichzeitig.`},dark:{title:`Die Karte bleibt dunkel`,text:`In dieser Höhe ist das Feld zu schwach, um den Chip der Karte zu betreiben. Mehr Verstärkung hilft hier nicht: Verstärkung macht den Reader zu einem besseren Zuhörer, sie sendet nicht mehr Strom.`},answer:{title:`Die Karte antwortet: ATQA 04 00`,text:`Die Karte kann nicht senden. Sie schaltet eine kleine Last an ihrer Spule 847.000-mal pro Sekunde (fc/16); die Antenne des Readers spürt ihr eigenes Feld wackeln und dekodiert 2 Bytes. Der Chip löst RxIRq aus, der IRQ-Draht fällt, der Reader-Task wacht auf.`},quiet:{title:`Die Karte antwortet… zu leise`,text:`Die Karte hat Strom und antwortet, aber bei dieser Verstärkung kann der Reader ihre winzigen Laständerungen nicht vom Rauschen unterscheiden. Dreh die Verstärkung hoch oder bring die Karte näher.`}},chart:{label:`Feldstärke an der Karte gegen die Höhe, auf logarithmischer Skala, mit dem Pegel, den die Karte zum Aufwachen braucht, und dem Pegel, den der Reader zum Hören ihrer Antwort braucht.`,x:`Kartenhöhe über der Antenne (mm)`,y:`Feld`,wakes:`Karte wacht oberhalb davon auf`,hears:`Reader hört sie oberhalb davon ({{db}} dB)`,works:`funktioniert: 0–{{mm}} mm`,nothing:`nichts funktioniert`}},memory3d:{legend:{keyA:`Schlüssel A (liest sich als 00)`,access:`Zugriffsbits`,user:`User-Byte`,keyB:`Schlüssel B · Wert`,uid:`UID + BCC`,text:`dein Text`},kinds:{maker:`Hersteller`,empty:`leer`,data:`Daten`,value:`Wert`,trailer:`Trailer`},captions:{auth:{title:`3-Pass-Authentifizierung`,text:`Der Chip fragt die Karte nach Sektor {{sector}} mit Schlüssel A; die Karte sendet eine zufällige Challenge, der Chip antwortet mit seiner eigenen, und beide beweisen, dass sie den Schlüssel kennen, ohne ihn je zu senden. Ab jetzt verschlüsselt Crypto1 jeden Frame.`},open:{title:`Sektor {{sector}}, offen`,text:`Mit Schlüssel A authentifiziert (der Werksschlüssel FF FF FF FF FF FF). Die Blöcke {{first}}–{{last}} lassen sich lesen. Schlüssel A liest sich als 00 zurück: Die Karte verrät ihn nie. Die Bytes 6–8 des Trailers sind die Zugriffsbits; Byte 9 ist frei.`},locked:{title:`Sektor {{sector}}, gesperrt`,text:`Die Blöcke {{first}}–{{last}} bleiben unlesbar, bis der Reader beweist, dass er den Schlüssel dieses Sektors kennt: Drück Authentifizieren.`}},labels:{maker:`Sektor 0 · Block 0 = Hersteller`,trailer:`Trailer: Schlüssel + Zugriffsbits`,last:`Sektor 15`},stage:`3D-Ansicht: die 16 Sektoren der Karte als Schränke mit je 4 Blöcken, der oberste Block jedes Sektors ist der Sektor-Trailer mit einem Schloss. Klick auf einen Sektor, um ihn zu öffnen.`,fallback:`Die Byte-Tabelle darunter funktioniert trotzdem.`,after:`Nach R5`,sector:`Sektor`,sectorN:`Sektor {{n}}`,authenticate:`🔑 Diesen Sektor authentifizieren`,byte:`Byte {{n}}`,lockedNote:`Gesperrt: Jeder Sektor hat eigene Schlüssel, also öffnet Sektor 1 nicht Sektor 2.`},edge:{experiments:{spi:{label:`SPI-Takt`,unit:`% falsche Bytes`,xTitle:`SPI-Takt (MHz)`,what:`64 zufällige Bytes ins FIFO des Chips und zurück, 20-mal bei jeder Taktgeschwindigkeit, plus zweimal VersionReg gelesen.`,look:`Der MFRC522 ist für 10 Mbit/s ausgelegt. Darüber entscheiden deine Drähte: Lange oder lose runden die Taktflanken ab, und MISO (der schwache Ausgang des Chips) fällt meist zuerst aus. Bei den üblichen 4 MHz willst du genau 0.`,markText:`Datenblatt-Max`},gain:{label:`Verstärkung gegen Abstand`,unit:`% gefunden`,xTitle:`Empfängerverstärkung (dB)`,what:`30 Aufwach- und Select-Versuche bei jeder Empfängerverstärkung, mit der Karte ruhig auf einer Höhe gehalten.`,look:`Verstärkung macht den Reader zu einem besseren Zuhörer; sie gibt der Karte nicht mehr Strom. Ganz nah geht jede Verstärkung. Weiter weg versagen niedrige zuerst, bis selbst 48 dB nicht mehr helfen, weil die Karte keinen Strom mehr hat (die 3D-Ansicht in R2 zeigt, warum).`,markText:`Standard`},timeout:{label:`Antwortzeit der Karte`,unit:`% WUPA beantwortet`,xTitle:`Chip-Timer (µs, außer ms angegeben)`,what:`Der Timer des Chips bestimmt, wie lange nach unserem Frame auf eine Antwort gewartet wird. Der Test verkleinert ihn Schritt für Schritt und zählt die Antworten auf WUPA, je 20 Versuche.`,look:`ISO 14443 sagt, dass eine Karte etwa 86 µs nach dem letzten Bit des Readers antwortet, und der Timer zählt in 25-µs-Ticks: Erwarte, dass Antworten zwischen 100 und 75 µs aufhören. Die 25 ms Standard sind 250-mal länger, als eine Karte braucht; das kostet ein leerer Poll.`,betweenText:`ISO: ~86 µs`},timing:{label:`Zeit pro Schritt`,unit:`µs, Durchschnitt`,xTitle:`Protokollschritt`,what:`40 volle Zyklen aus WUPA, dem letzten SELECT-Frame, Authentifizierung und einem Blocklesen, jeweils vom Start bis zum Ende des Befehls gemessen.`,look:`Der gestrichelte Umriss ist reine Sendezeit bei 106 kbit/s; alles darüber ist SPI-Verkehr und die eigene Arbeit des ESP32. Die Authentifizierung besteht aus drei Austauschen im Chip, also erwarte, dass sie am langsamsten ist.`,ghostText:`nur Sendezeit`},irq:{label:`Polling gegen IRQ`,unit:`SPI-Zugriffe pro WUPA`,xTitle:`wie der Reader-Task wartet`,what:`30 WUPAs, während ComIrqReg per SPI abgefragt wird, dann 30, die schlafen, bis der IRQ-Draht feuert, mit Zählung der SPI-Zugriffe pro Befehl.`,look:`Mit Karte sind beide schnell fertig, aber Polling hält den Bus beschäftigt, während es wartet. Lauf es nochmal ohne Karte: Jedes WUPA wartet jetzt den 25-ms-Timer ab, und die Zahl beim Polling schießt hoch, während die bei IRQ gleich bleibt.`},crc:{label:`CRC: Chip gegen CPU`,unit:`µs pro Frame`,xTitle:`wer CRC_A berechnet`,what:`300 zufällige Frames: CRC_A vom Koprozessor des Chips (die Bytes gehen per SPI hin und zurück) und vom ESP32 (dieselben fünf Zeilen wie in rfid_format.h).`,look:`Beide müssen bei jedem Frame übereinstimmen: 0 Abweichungen. Der Koprozessor selbst ist schnell, aber der SPI-Hin-und-Rück-Weg kostet weit mehr, als der ESP32 fürs Rechnen braucht: Hier verliert das Auslagern.`},stress:{label:`Stresslauf`,unit:`Zyklen`,xTitle:`Ergebnis jedes Zyklus aus Aufwecken → Select → Auth → Lesen`,what:`Hunderte komplette Zyklen am Stück: aufwecken, selecten, authentifizieren, Block 4 lesen, anhalten. Jedes Ergebnis gezählt.`,look:`Ruhig und nah gehalten, erwarte 99 % oder besser. Heb oder kipp die Karte langsam, während es läuft: Fehlschläge beginnen als „absent“ (keine Antwort), dann tauchen CRC- und Protokollfehler genau am Rand der Reichweite auf.`}},tabs:`Experiment`,solid_one:`Voll: deine {{count}} Zeile. Dünner Umriss neben jedem Balken: das Beispiel.`,solid_other:`Voll: deine {{count}} Zeilen. Dünner Umriss neben jedem Balken: das Beispiel.`,noRows:`Keine Zeilen erkannt: Füg die Zeilen unter der Kopfzeile der Tabelle ein.`,example:`Beispielzahlen (ein typischer RC522 an 15-cm-Drähten), nicht dein Board. Füg unten deine Tabelle ein, um sie zu ersetzen.`,paste:`Füg die Tabelle aus dem seriellen Monitor ein (die Zeitstempel dürfen bleiben):`,placeholder:`z. B.   1     0.0 %        0 / 20`,chart:{label:`{{name}}: {{unit}} pro {{x}}. {{values}}`,bar:`{{name}}: {{value}} {{unit}}`,barWithExample:`{{name}}: {{value}} {{unit}} (Beispiel {{example}})`,dashed:`gestrichelt: {{text}}`}},screens:{chip:{when:`Die erste Ansicht zum Prüfen nach dem Verkabeln (R1). Doppelklick startet den Selbsttest.`,parts:[`Der Chip. Seine Mitte leuchtet türkis, solange der Chip antwortet; sie kann nicht leuchten, wenn VersionReg 00h oder FFh liest.`,`VersionReg: 92h = MFRC522 v2.0, 91h = v1.0, andere Werte = ein Klon. 00h oder FFh heißt, nichts hat geantwortet: Prüf die Verkabelung.`,`Selbsttest: „not run“, bis du selftest tippst (oder doppelklickst). Dann „passed“ (NXP-Chip, passt zum Datenblatt), „consistent“ (Klon, zwei Läufe stimmen überein), „not supported“ (ein Klon ohne ihn) oder „FAILED“.`,`SPI-Takt: standardmäßig 4 MHz. Wird bernsteinfarben über der 10-MHz-Angabe des Chips (spi <MHz>).`,`Wie der Reader-Task auf den Chip wartet: „IRQ wire“, oder „polling“, wenn IRQ nicht verkabelt ist (die Firmware schaltet selbst um und sagt es).`,`Empfängerverstärkung, 18 bis 48 dB (gain <0-7>); standardmäßig 33 dB.`,`Bus-Zähler: SPI-Zugriffe und Befehle. Sie zählen ständig hoch, etwa 12 Polls pro Sekunde: Der Reader-Task lebt.`,`Karten-Punkt: türkis mit Ring, solange eine Karte im Feld ist. Auf jeder Ansicht gleich.`,`Fußzeile links: was ein Doppelklick auf dieser Ansicht tut.`,`Fußzeile rechts: das letzte Ergebnis. Türkis = gut, koralle = ein Problem, bernstein mit wachsender Linie = beschäftigt.`]},card:{when:`Die Ansicht, mit der das Board startet. Zeigt die Karte, die gerade im Feld ist. Doppelklick startet das Inventar.`,parts:[`Die Antenne und ihr Feld: immer animiert, mit oder ohne Karte.`,`Hier erscheint eine Karte, wenn eine im Feld ist; das kleine Quadrat ist ihr Chip.`,`Die UID: die Seriennummer der Karte, wie die Antikollision sie gelesen hat.`,`Der Kartentyp, aus SAK dekodiert.`,`ATQA (00 04) und SAK (08): die Antworten der Karte auf Aufwecken und Select. UID-Größe: 4, 7 oder 10 Bytes.`,`Leserate: wie viele der letzten 20 Polls die Karte gefunden haben. 100 % = stabil; bernstein oder koralle = Rand der Reichweite.`,`Nur mit zwei Karten auf dem Leser: das Bit, bei dem sich ihre UIDs zuerst unterscheiden (R3).`]},trace:{when:`Der Sniffer: die Frames des letzten Aufweckens oder Befehls der Karte. Doppelklick schaltet ihn an oder aus.`,parts:[`Zeit in ms seit dem ersten Frame dieses Austauschs.`,`> Reader zur Karte (bernstein), < Karte zum Reader (türkis).`,`Die Bytes in der Luft. Graue Bytes waren in der Luft verschlüsselt (nach der Authentifizierung); du siehst den Klartext.`,`Was der Frame ist: WUPA, ATQA, ANTICOLL, SELECT, SAK, HLTA, READ…`]},memory:{when:`Der letzte Dump, Block für Block. Doppelklick startet dump (halt die Karte ruhig).`,parts:[`Eine Spalte pro Sektor, 0 bis 15.`,`Block 0 (bernstein): der Herstellerblock mit der UID. Schreibgeschützt.`,`Datenblöcke: dunkel = nur Nullen, grün = etwas geschrieben, blau = ein Wertblock (Guthaben).`,`Die untere Reihe: der Trailer jedes Sektors (Schlüssel + Zugriffsbits), koralle. Das Lab schreibt diese nie.`,`Von welcher Karte dieser Dump stammt.`]},credits:{when:`Der Guthabenzähler in den Blöcken 8 und 9 (R5). Doppelklick addiert 1 Guthaben.`,parts:[`Eine Münze pro 10 Guthaben (bis zu 8).`,`Der Wert in Block 8, wie die Karte ihn berechnet hat.`,`Das Backup in Block 9: der Wert vor der letzten Änderung.`]},edge:{when:`Das letzte Experiment des Edge-Labs als Balkendiagramm (R6). Doppelklick startet das nächste Experiment.`,parts:[`Welches Experiment.`,`Ein Balken pro ausprobierter Einstellung, alle auf einer Skala; der Wert steht über jedem Balken.`,`Ein umrandeter Balken markiert die Referenz: die Datenblattgrenze oder den Standard.`,`Das Fazit in einer Zeile, auch im Monitor mit der vollen Tabelle ausgegeben.`]}},views:{chip:`Chip`,card:`Karte`,trace:`Trace`,memory:`Speicher`,credits:`Guthaben`,edge:`Grenzbereich`,cards:`Karten`,stage:`Bühne`,door:`Tür`,log:`Log`},screen:{tabs:`Bildschirmansicht`,tab:`{{n}} · {{view}}`,example:`Beispiel für die Ansicht „{{view}}“. Die Liste darunter erklärt jeden nummerierten Teil.`},preview:{field:{card:`Karte auflegen`,tag:`Tag auflegen`,both:`beide`,none:`entfernen`},button:`Taster: klicken für nächste Ansicht, doppelklicken für die Aktion dieser Ansicht, halten zum Pausieren des Pollings`,views:`Ansichten`,status:`Ansicht {{view}} · Polling`,statusPaused:`Ansicht {{view}} · pausiert`,cards:`Karten auf dem Leser`,screen:`Simulierter Board-Bildschirm: Ansicht {{view}}`,example:`Beispieldaten: Die UIDs, Zeiten und Zahlen sind erfunden. Dein Board gibt seine eigenen aus.`,quick:`Schnellbefehle`},friends:{cast:{fox:{what:`ein flinker kleiner Fuchs`,move:`dreht sich zweimal im Sprung`,fx:`goldene Sterne`,sky:`Sonnenuntergang`},robot:{what:`ein tanzender Roboter`,move:`tanzt mit schwingenden Armen`,fx:`Funken`,sky:`tiefes Türkis`},dragon:{what:`ein winziger Drache`,move:`fliegt eine Schleife`,fx:`Feuer`,sky:`Vulkanorange`},penguin:{what:`ein rutschender Pinguin`,move:`rutscht auf dem Bauch im Kreis`,fx:`Schnee`,sky:`Winterblau`},alien:{what:`ein freundlicher Alien`,move:`beamt sich hoch und dreht sich`,fx:`Ringe`,sky:`Weltraumviolett`},cat:{what:`eine kuschelige Katze`,move:`wackelt fröhlich`,fx:`Herzen`,sky:`Bonbonrosa`},frog:{what:`ein hüpfender Frosch`,move:`springt hoch mit Salto`,fx:`Blasen`,sky:`Teich`},unicorn:{what:`ein magisches Einhorn`,move:`galoppiert hin und her`,fx:`Regenbogensterne`,sky:`Pastell`}},chosen:`<b>{{name}}</b>, Id <code>{{id}}</code> (das Einzige, was das Board für die Karte speichert). In der App: <b>{{move}}</b>, {{fx}}, ein Himmel in {{sky}} und eine eigene Melodie. Gib ihn Karte 1 mit dem seriellen Befehl <code>give 1 {{id}}</code> oder zieh ihn in der App hinein.`,pick:`Drück einen Freund: Er springt, und du siehst, was er auf dem Bildschirm des Boards und in der 3D-App macht.`,taps:`Taps`,tapWhite:`Tap: weiße Karte`,tapTag:`Tap: Schlüsselanhänger`,tapNew:`Tap: eine neue Karte`,app:`Die App und der Taster`,move:`App: <friend/> auf Karte <card/> ziehen`,whichFriend:`Welcher Freund`,whichCard:`Welche Karte`,moveIn:`einziehen lassen`,nextView:`Taster: nächste Ansicht`,screen:`Simulierter Freunde-Bildschirm: Ansicht {{view}}`,example:`Beispieldaten. Das Board zeichnet dieselben Formen (characters.h); die App zeigt sie in 3D.`},door:{taps:`Taps`,tap:{white:`Tap: weiße Karte (Bewohner)`,tag:`Tap: Schlüsselanhänger (Gast)`,stranger:`Tap: eine Karte, die nicht in der Liste ist`},app:`Die App und der Taster`,block:`App: weiße Karte sperren`,lockdown:`App: Lockdown`,open:`App: 5 s öffnen`,copy:`App: weiße Karte → Schlüsselanhänger kopieren`,nextView:`Taster: nächste Ansicht`,screen:`Simulierter Tür-Bildschirm: Ansicht {{view}}`,example:`Beispieldaten. Im Lab macht die App die „App:“-Aktionen und deine Hände die Taps.`},doorRules:{tappedAt:`angetippt um`,front:`Haustür`,adminRoom:`Admin-Raum`,listed:`in der Liste`,role:`Rolle`,roles:{resident:`Bewohner`,guest:`Gast`,maintenance:`Wartung`,admin:`Admin`},blocked:`gesperrt`,endDate:`Enddatum`,until:{none:`keins`,future:`nächste Woche`,past:`gestern`},hoursFrom:`Zeiten von`,to:`bis`,uses:`Nutzungen`,unlimited:`unbegrenzt`,usesLeft_one:`{{count}} übrig`,usesLeft_other:`{{count}} übrig`,lockdown:`Lockdown`,synced:`Board hat Internetzeit`,timeNow:`Uhrzeit jetzt`,rules:{unknown:{name:`In der Liste?`,says:`unbekannte Karte`},blocked:{name:`Gesperrt?`,says:`gesperrt`},admin:{name:`Admin-Raum: eine Admin-Karte?`,says:`nur Admins`},lockdown:{name:`Lockdown (Wartung und Admin bleiben offen)`,says:`Lockdown`},clock:{name:`Braucht eine Uhr, und hat eine?`,says:`noch keine Uhr`},expired:{name:`Vor ihrem Enddatum?`,says:`abgelaufen`},hours:{name:`Innerhalb ihrer Zeiten?`,says:`außerhalb der Zeiten`},uses:{name:`Nutzungen übrig?`,says:`keine Nutzungen übrig`}},trail:{skip:`nicht geprüft`,pass:`ja`,stop:`nein → {{says}}`},allPassed:`Alle bestanden`,openNote:`OFFEN (die Nutzungen eines Gasts sinken um eins)`,denied:`<now>DENIED · {{says}}</now> die erste Regel, die Nein sagt, gewinnt; die übrigen werden nicht geprüft.`,granted:`<now>OPEN</now> jede Regel bestanden.`},copy:{zeros:`Nullen`,value:`Wert {{n}}`,keys:`Schlüssel`,closed:`öffnet sich nicht`,quoted:`„{{text}}“`,cell:`Block {{n}}: {{text}}`,rest:`Sektoren 3-15: nicht angefasst`,save:`Weiße Karte speichern`,copy:`Weiße Karte → Schlüsselanhänger kopieren`,again:`Neu starten`,otherKey:`Sektor 2 des Schlüsselanhängers hat einen anderen Schlüssel`,legend:{uid:`Block 0: UID + Herstellerdaten, nie geschrieben`,lab:`Lab-Blöcke: gespeichert und kopiert`,trailer:`Trailer: Schlüssel + Zugriffsbits, nie geschrieben`,sector0:`Daten von Sektor 0: außerhalb des Lab-Bereichs`},read:`Lies zuerst die weiße Karte: 6 von 6 Blöcken.`,saved:`<now>6 von 6 gespeichert</now>Schnappschuss „White card“ auf dem Board (NVS). Block 0 und die Trailer gehören nicht dazu.`,copied:`{{done}} von 6 kopiert`,skipped:`Sektor 2 hat sich mit dem Werksschlüssel nicht geöffnet, also wurden die Blöcke 8-10 übersprungen: Das Board erzwingt nie einen Sektor.`,allCopied:`Jeder Block geschrieben und zurückgelesen.`,uidStays:`Die UID ist weiter <b>{{uid}}</b>: Ein Tap mit dem Schlüsselanhänger wird als <b>Key tag</b> nachgeschlagen, nicht als White card. Die Tür entscheidet nach UID, und die UID hat sich nicht bewegt.`}};export{e as default};
